"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[183],{4183:(e,a,s)=>{s.d(a,{C:()=>o});let o=[{id:"major-pentatonic",name:"Pentat\xf2nica major",formula:"1 2 3 5 6",notes:["C","D","E","G","A"],description:"La pentat\xf2nica major \xe9s la base del so country cl\xe0ssic i del bluegrass. \xc9s la mateixa escala que la pentat\xf2nica menor de la seva relativa menor, per\xf2 amb la t\xf2nica despla\xe7ada. Son alegre, oberta i perfecta per a frases mel\xf2diques i doble stops.",usage:"Sobre acords majors i progressions I-IV-V en country, bluegrass i honky-tonk. \xc9s la primera escala que cal dominar per a solos i fills mel\xf2dics.",chordTypes:["C","G","F","Am"],examples:[{artist:"Chet Atkins",song:"Mr. Sandman",context:"Fraseig mel\xf2dic de pentat\xf2nica major sobre la melodia."},{artist:"Don Rich",song:"Together Again",context:"Fills i solos de pentat\xf2nica major amb doble stops."},{artist:"James Burton",song:"Sweet Dreams",context:"Licks de pentat\xf2nica major amb bending expressiu."}],exercises:[{title:"Seq\xfc\xe8ncies de 3 notes",description:"Toca la pentat\xf2nica major en una sola posici\xf3 fent grups de tres notes ascendents i descendents.",tips:["Mant\xe9n la m\xe0 quieta i canvia de corda amb moviments m\xednims.","Comen\xe7a lent i augmenta el tempo amb metr\xf2nom."]},{title:"Doble stops en terceres",description:"Toca la pentat\xf2nica major en doble stops de tercera (C-E, D-G, E-A) sobre la progressi\xf3 C-G-F.",tips:["Pica les dues cordes alhora amb un atac net.","Escolta com cada doble stop ressona sobre l'acord de fons."]},{title:"Fraseig amb bends",description:"Crea frases curtes de 2-3 notes acabades amb un bend de to sencer cap a la t\xf2nica.",tips:["El bend ha de sonar afinat: compara amb la nota oberta.","Acaba cada frase amb un vibrato lleuger."]}]},{id:"minor-pentatonic",name:"Pentat\xf2nica menor",formula:"1 b3 4 5 b7",notes:["C","Eb","F","G","Bb"],description:"La pentat\xf2nica menor \xe9s l'escala m\xe9s utilitzada en el country modern i el rockabilly. \xc9s la relativa menor de la pentat\xf2nica major i aporta un so m\xe9s fosc i bluesy. \xc9s la base de la majoria de licks de guitarra country el\xe8ctrica.",usage:"Sobre acords menors, progressions blues i per afegir tensi\xf3 en solos country moderns. Tamb\xe9 funciona sobre acords majors en contextos bluesy (sobre el V).",chordTypes:["Cm","Gm","F","Bb"],examples:[{artist:"Brad Paisley",song:"Whiskey Lullaby",context:"Solos i fills amb pentat\xf2nica menor i bends bluesy."},{artist:"Albert Lee",song:"Country Boy",context:"Licks r\xe0pids de pentat\xf2nica menor amb alternate picking."},{artist:"Danny Gatton",song:"Funhouse",context:"Fraseig de pentat\xf2nica menor amb tocs de blues i jazz."}],exercises:[{title:"Licks de 4 notes",description:"Toca la pentat\xf2nica menor en una posici\xf3 fent licks de quatre notes amb alternate picking estricte.",tips:["Alterna sempre down-up-down-up.","Practica cada lick sobre un acord de Cm de fons."]},{title:"Bends de to i de semit\xf2",description:"Practica bends de to sencer i de semit\xf2 sobre les notes de la pentat\xf2nica menor.",tips:["Usa dos dits per fer el bend i guanya for\xe7a.","Comprova l'afinaci\xf3 del bend amb la nota oberta de refer\xe8ncia."]},{title:"Fraseig cridaner",description:"Crea frases curtes que comencin en temps febles i acabin amb un bend o un slide cap a la t\xf2nica.",tips:["Respira entre frases: deixa espai.","Imagina que la guitarra canta una melodia vocal."]}]},{id:"blues-scale",name:"Escala de blues",formula:"1 b3 4 b5 5 b7",notes:["C","Eb","F","Gb","G","Bb"],description:"L'escala de blues \xe9s la pentat\xf2nica menor amb la blue note (b5) afegida. Aquesta nota d\xf3na el car\xe0cter bluesy i expressiu tan caracter\xedstic del country el\xe8ctric i del rockabilly. \xc9s imprescindible per a licks amb bends i slides.",usage:"Sobre progressions de blues en country, rockabilly i honky-tonk. La blue note s'utilitza com a nota de pas o com a bend per crear tensi\xf3 i resoluci\xf3.",chordTypes:["C7","F7","G7","Cm"],examples:[{artist:"Danny Gatton",song:"Elmira St. Boogie",context:"Licks de blues scale amb bends i slides sobre un boogie."},{artist:"Jerry Reed",song:"The Claw",context:"Fraseig de blues scale amb atac percussiu i h\xedbrid."},{artist:"James Burton",song:"Suzie Q",context:"Solos de blues scale amb bends expressius i vibrato."}],exercises:[{title:"Blue note amb bend",description:"Toca la blue note (Gb) i fes-li un bend de semit\xf2 cap a la quinta (G) sobre un acord de C7.",tips:["El bend de la blue note \xe9s el gest m\xe9s caracter\xedstic del blues.","Practica el vibrato sobre la nota resolta."]},{title:"Licks de blues en una posici\xf3",description:"Apr\xe8n tres licks cl\xe0ssics de blues scale en la posici\xf3 de C i toca'ls sobre un backing de 12 compassos.",tips:["Memoritza els licks en diferents cordes.","Toca'ls amb groove, no nom\xe9s amb velocitat."]},{title:"Slides entre notes",description:"Practica slides ascendents i descendents entre les notes de la blues scale.",tips:["El slide ha de ser net i sense soroll de corda.","Combina slides amb bends per a un so m\xe9s vocal."]}]},{id:"mixolydian",name:"Mode mixolidi",formula:"1 2 3 4 5 6 b7",notes:["C","D","E","F","G","A","Bb"],description:"El mode mixolidi \xe9s l'escala major amb la setena menor (b7). \xc9s el so fonamental del country, el bluegrass i el rockabilly, ja que la b7 crea la tensi\xf3 que es resol sobre els acords de setena dominant. \xc9s l'escala m\xe9s important per a solos country sobre acords de setena.",usage:"Sobre acords de setena dominant (C7, G7, F7) i progressions I-IV-V. \xc9s la base dels solos country cl\xe0ssics i dels fills mel\xf2dics sobre acords de setena.",chordTypes:["C7","G7","F7","D7"],examples:[{artist:"Brent Mason",song:"Hot Wired",context:"Solos de mixolidi amb alternate picking i doble stops."},{artist:"Brad Paisley",song:"Mud on the Tires",context:"Fraseig de mixolidi amb bends i licks mel\xf2dics."},{artist:"Albert Lee",song:"Country Boy",context:"Licks r\xe0pids de mixolidi sobre acords de setena."}],exercises:[{title:"Arpegis sobre C7",description:"Toca l'escala mixolidi de C destacant les notes de l'acord C7 (C-E-G-Bb) en cada posici\xf3.",tips:["Marca les notes de l'acord amb un accent.","Visualitza l'arpegi dins de l'escala."]},{title:"Licks de b7",description:"Crea licks que acabin o comencin amb la b7 (Bb) per crear tensi\xf3 que es resolgui cap a la t\xf2nica.",tips:["La b7 \xe9s la nota que d\xf3na el so country.","Resol sempre cap a una nota de l'acord."]},{title:"Seq\xfc\xe8ncies de 4 notes",description:"Toca seq\xfc\xe8ncies de quatre notes per l'escala mixolidi en una posici\xf3, ascendents i descendents.",tips:["Usa alternate picking estricte.","Augmenta el tempo gradualment amb metr\xf2nom."]}]},{id:"dorian",name:"Mode d\xf2ric",formula:"1 2 b3 4 5 6 b7",notes:["C","D","Eb","F","G","A","Bb"],description:"El mode d\xf2ric \xe9s la escala menor amb la sisena major (6). Aquesta sisena major li d\xf3na un so m\xe9s brillant i menys fosc que la menor natural. \xc9s molt utilitzat en el country modern i en el bluegrass per a solos sobre acords menors.",usage:"Sobre acords menors (Cm, Gm, Dm) i progressions menors en country i bluegrass. La sisena major (A) \xe9s la nota que el distingeix de la menor natural.",chordTypes:["Cm","Gm","Dm","Am"],examples:[{artist:"Brent Mason",song:"Hot Wired",context:"Passatges de d\xf2ric sobre acords menors en solos country."},{artist:"Brad Paisley",song:"The World",context:"Fraseig de d\xf2ric amb la sisena major com a color."},{artist:"Jerry Reed",song:"East Bound and Down",context:"Licks de d\xf2ric amb atac r\xedtmic i h\xedbrid."}],exercises:[{title:"Destacar la sisena",description:"Toca el d\xf2ric de C destacant la sisena major (A) sobre un acord de Cm de fons.",tips:["La sisena \xe9s la nota que d\xf3na el color d\xf2ric.","Alterna entre la sisena i la setena menor per sentir la difer\xe8ncia."]},{title:"Arpegis menors",description:"Toca l'arpegi de Cm (C-Eb-G) dins de l'escala d\xf2rica i afegeix la sisena com a nota de pas.",tips:["Marca les notes de l'arpegi.","Practica sobre una progressi\xf3 Cm-Gm."]},{title:"Fraseig mel\xf2dic",description:"Crea frases mel\xf2diques de d\xf2ric que comencin en la t\xf2nica i acabin en la sisena o la t\xf2nica.",tips:["Pensa en frases vocals, no en exercicis.","Deixa espai entre frases."]}]},{id:"major",name:"Escala major",formula:"1 2 3 4 5 6 7",notes:["C","D","E","F","G","A","B"],description:"L'escala major \xe9s la base de tota la m\xfasica occidental i del country. Totes les altres escales i modes deriven d'ella. En country s'utilitza per a melodies, arpegis i per entendre la relaci\xf3 entre acords i escales.",usage:"Sobre acords majors i progressions diat\xf2niques. \xc9s fonamental per entendre els modes i per construir arpegis i acords.",chordTypes:["C","G","F","Am","Dm"],examples:[{artist:"Chet Atkins",song:"Mr. Sandman",context:"Melodies i arpegis de l'escala major."},{artist:"Merle Travis",song:"I Am a Pilgrim",context:"Fraseig de l'escala major amb fingerpicking."},{artist:"Don Rich",song:"Together Again",context:"Fills mel\xf2dics de l'escala major amb doble stops."}],exercises:[{title:"Arpegis de l'escala",description:"Toca els arpegis de cada grau de l'escala major de C (C, Dm, Em, F, G, Am, Bdim).",tips:["Visualitza cada arpegi dins de la posici\xf3 de l'escala.","Practica sobre la progressi\xf3 C-Am-F-G."]},{title:"Seq\xfc\xe8ncies diat\xf2niques",description:"Toca seq\xfc\xe8ncies de terceres i de quartes per l'escala major de C.",tips:["Les terceres s\xf3n la base dels doble stops country.","Mant\xe9n un tempo constant."]},{title:"Melodies per graus",description:'Toca la melodia de "Amazing Grace" o una melodia senzilla utilitzant nom\xe9s notes de l\'escala major de C.',tips:["Escolta la melodia i canta-la abans de tocar-la.","Toca la melodia en diferents posicions."]}]},{id:"natural-minor",name:"Menor natural (e\xf2lic)",formula:"1 2 b3 4 5 b6 b7",notes:["C","D","Eb","F","G","Ab","Bb"],description:"La menor natural \xe9s la relativa menor de l'escala major i t\xe9 un so m\xe9s fosc i melanc\xf2lic. \xc9s la base de moltes can\xe7ons country i bluegrass en tonalitat menor. La sisena menor (Ab) \xe9s la nota que la distingeix del mode d\xf2ric.",usage:"Sobre acords menors i progressions menors en country i bluegrass. S'utilitza per a melodies i solos en tonalitats menors.",chordTypes:["Cm","Gm","Fm","Ab"],examples:[{artist:"Brad Paisley",song:"Whiskey Lullaby",context:"Melodies i solos en menor natural amb un so melanc\xf2lic."},{artist:"Albert Lee",song:"Country Boy",context:"Passatges de menor natural en solos r\xe0pids."},{artist:"Chet Atkins",song:"Black Mountain Rag",context:"Fraseig de menor natural amb fingerpicking."}],exercises:[{title:"Arpegis menors",description:"Toca l'arpegi de Cm (C-Eb-G) dins de l'escala menor natural i afegeix la b6 i la b7 com a colors.",tips:["Marca les notes de l'arpegi.","Practica sobre una progressi\xf3 Cm-Ab-Eb-Bb."]},{title:"Contrast d\xf2ric-menor",description:"Toca la mateixa frase en d\xf2ric (amb la 6 major) i en menor natural (amb la b6) per sentir la difer\xe8ncia.",tips:["La b6 d\xf3na un so m\xe9s fosc i melanc\xf2lic.","Usa la b6 com a nota de pas cap a la quinta."]},{title:"Melodies menors",description:'Toca una melodia senzilla en menor natural de C, com "Greensleeves", en diferents posicions.',tips:["Canta la melodia abans de tocar-la.","Practica el fraseig amb din\xe0miques."]}]},{id:"country-scale",name:"Country scale (mixolidi amb b3)",formula:"1 2 b3 3 4 5 6 b7",notes:["C","D","Eb","E","F","G","A","Bb"],description:"La country scale \xe9s el mode mixolidi amb la tercera menor (b3) afegida com a nota crom\xe0tica de pas. Aquesta nota d\xf3na el so country caracter\xedstic, amb un toc bluesy que es resol cap a la tercera major. \xc9s l'escala definit\xf2ria del country el\xe8ctric modern.",usage:"Sobre acords de setena dominant (C7, G7) en country modern i rockabilly. La b3 s'utilitza com a nota de pas crom\xe0tica cap a la tercera major (E).",chordTypes:["C7","G7","F7","C"],examples:[{artist:"Brent Mason",song:"Hot Wired",context:"Licks de country scale amb la b3 com a nota de pas."},{artist:"Brad Paisley",song:"Mud on the Tires",context:"Fraseig de country scale amb bends i doble stops."},{artist:"Albert Lee",song:"Country Boy",context:"Licks r\xe0pids de country scale amb alternate picking."}],exercises:[{title:"La b3 com a nota de pas",description:"Toca la seq\xfc\xe8ncia Eb-E (b3 a 3) com a nota de pas crom\xe0tica sobre un acord de C7.",tips:["La b3 sempre es resol cap a la tercera major.","Practica el pas crom\xe0tic en diferents cordes."]},{title:"Licks de country scale",description:"Apr\xe8n tres licks cl\xe0ssics de country scale que utilitzin la b3 i toca'ls sobre una progressi\xf3 C7-G7.",tips:["Usa alternate picking estricte.","Acaba cada lick amb un bend o un vibrato."]},{title:"Doble stops amb b3",description:"Toca doble stops que incloguin la b3 i la tercera major per crear el so country caracter\xedstic.",tips:["Pica les dues cordes alhora.","Escolta com la b3 crea tensi\xf3 que es resol."]}]},{id:"double-stop-scale",name:"Escala de doble stops",formula:"1 2 3 4 5 6 b7 (en terceres)",notes:["C","D","E","F","G","A","Bb"],description:"L'escala de doble stops no \xe9s una escala pr\xf2piament dita, sin\xf3 una manera de tocar l'escala mixolidi en terceres (dues notes alhora). \xc9s el so m\xe9s caracter\xedstic del country cl\xe0ssic, utilitzat per Don Rich, Chet Atkins i tots els grans del Bakersfield sound.",usage:"Sobre acords majors i de setena dominant en country cl\xe0ssic i Bakersfield. Els doble stops en terceres creen el so ple i brillant del country tradicional.",chordTypes:["C","G","F","C7"],examples:[{artist:"Don Rich",song:"Together Again",context:"Doble stops en terceres sobre la progressi\xf3 I-IV-V."},{artist:"Chet Atkins",song:"Mr. Sandman",context:"Doble stops mel\xf2dics amb fingerpicking."},{artist:"James Burton",song:"Sweet Dreams",context:"Doble stops amb bends i vibrato."}],exercises:[{title:"Terceres diat\xf2niques",description:"Toca l'escala mixolidi de C en terceres diat\xf2niques (C-E, D-F, E-G, F-A, G-Bb, A-C).",tips:["Pica les dues cordes alhora amb un atac net.","Mant\xe9n les dues notes afinades i equilibrades."]},{title:"Doble stops sobre la progressi\xf3",description:"Toca doble stops en terceres sobre la progressi\xf3 C-G-F, canviant de posici\xf3 amb cada acord.",tips:["Escolta com cada doble stop ressona sobre l'acord de fons.","Usa el dit anular i el menovell per als doble stops."]},{title:"Doble stops amb bends",description:"Practica doble stops on una de les notes fa un bend cap a la seg\xfcent nota de l'escala.",tips:["El bend ha de sonar afinat en les dues notes.","Combina doble stops amb frases d'una sola nota."]}]},{id:"bebop-major",name:"Bebop major",formula:"1 2 3 4 5 6 b7 7",notes:["C","D","E","F","G","A","Bb","B"],description:"L'escala bebop major \xe9s l'escala major amb la setena menor (b7) afegida com a nota de pas. Aquesta nota extra permet que les frases de vuit notes caiguin en temps forts sobre notes de l'acord. \xc9s molt utilitzada en el country modern i el country-jazz per a solos sofisticats.",usage:"Sobre acords majors i de setena dominant en country modern i country-jazz. La b7 s'utilitza com a nota de pas crom\xe0tica per crear frases fluides.",chordTypes:["C","C7","G","F"],examples:[{artist:"Brent Mason",song:"Hot Wired",context:"Frases de bebop major amb alternate picking i cromatismes."},{artist:"Danny Gatton",song:"Funhouse",context:"Solos de bebop major amb tocs de jazz i country."},{artist:"Albert Lee",song:"Country Boy",context:"Licks de bebop major amb velocitat i precisi\xf3."}],exercises:[{title:"Frases de 8 notes",description:"Toca l'escala bebop major de C en frases de vuit notes, comen\xe7ant i acabant en notes de l'acord.",tips:["La b7 \xe9s una nota de pas, no una nota d'arribada.","Compta els temps forts per sentir on cauen les notes de l'acord."]},{title:"Cromatismes de pas",description:"Practica el pas crom\xe0tic Bb-B (b7 a 7) dins de frases de l'escala bebop major.",tips:["El cromatisme ha de sonar com una nota de pas natural.","Usa alternate picking per a les notes crom\xe0tiques."]},{title:"Licks de bebop",description:"Apr\xe8n tres licks de bebop major sobre una progressi\xf3 C-Am-F-G.",tips:["Memoritza els licks en diferents posicions.","Toca'ls amb swing i groove."]}]},{id:"bebop-dominant",name:"Bebop dominant",formula:"1 2 3 4 5 6 b7 7",notes:["C","D","E","F","G","A","Bb","B"],description:"L'escala bebop dominant \xe9s el mode mixolidi amb la setena major (7) afegida com a nota de pas. \xc9s l'escala m\xe9s utilitzada per a solos sobre acords de setena dominant en country modern i country-jazz. La setena major crea un cromatisme que fa que les frases caiguin perfectament en els temps forts.",usage:"Sobre acords de setena dominant (C7, G7, F7) en country modern, rockabilly i country-jazz. \xc9s ideal per a solos llargs i frases fluides sobre progressions de blues i I-IV-V.",chordTypes:["C7","G7","F7","D7"],examples:[{artist:"Brent Mason",song:"Hot Wired",context:"Solos de bebop dominant amb alternate picking i cromatismes."},{artist:"Danny Gatton",song:"Elmira St. Boogie",context:"Frases de bebop dominant sobre un boogie de setena."},{artist:"Albert Lee",song:"Country Boy",context:"Licks de bebop dominant amb velocitat i precisi\xf3."}],exercises:[{title:"Frases de 8 notes sobre C7",description:"Toca l'escala bebop dominant de C en frases de vuit notes sobre un acord de C7 de fons.",tips:["La setena major (B) \xe9s una nota de pas cap a la t\xf2nica.","Compta els temps forts per sentir les notes de l'acord."]},{title:"Cromatisme B-Bb",description:"Practica el pas crom\xe0tic B-Bb (7 a b7) dins de frases de l'escala bebop dominant.",tips:["El cromatisme ha de sonar natural i fluid.","Usa alternate picking per a les notes crom\xe0tiques."]},{title:"Licks sobre la progressi\xf3",description:"Apr\xe8n tres licks de bebop dominant sobre una progressi\xf3 C7-F7-G7.",tips:["Memoritza els licks en diferents posicions.","Toca'ls amb groove i swing."]}]},{id:"chromatic",name:"Escala crom\xe0tica (per a licks)",formula:"1 b2 2 b3 3 4 b5 5 b6 6 b7 7",notes:["C","Db","D","Eb","E","F","Gb","G","Ab","A","Bb","B"],description:"L'escala crom\xe0tica inclou les dotze notes de l'octava. No s'utilitza com a escala mel\xf2dica, sin\xf3 com a font de notes de pas crom\xe0tiques per crear licks i frases expressives. \xc9s essencial per al country modern, on els cromatismes afegeixen tensi\xf3 i sofisticaci\xf3 als solos.",usage:"Sobre qualsevol acord, com a notes de pas crom\xe0tiques que es resolen cap a notes de l'acord. S'utilitza per crear licks r\xe0pids i frases amb tensi\xf3 i resoluci\xf3.",chordTypes:["C","C7","G","F","Am"],examples:[{artist:"Brent Mason",song:"Hot Wired",context:"Licks crom\xe0tics r\xe0pids amb alternate picking."},{artist:"Danny Gatton",song:"Funhouse",context:"Cromatismes i frases de jazz-country."},{artist:"Albert Lee",song:"Country Boy",context:"Passatges crom\xe0tics amb velocitat i precisi\xf3."}],exercises:[{title:"Notes de pas crom\xe0tiques",description:"Toca frases de l'escala mixolidi i afegeix notes crom\xe0tiques de pas entre les notes de l'acord.",tips:["Les notes crom\xe0tiques sempre es resolen cap a una nota de l'acord.","No abusis dels cromatismes: usa'ls amb intenci\xf3."]},{title:"Licks crom\xe0tics r\xe0pids",description:"Apr\xe8n tres licks crom\xe0tics r\xe0pids i toca'ls sobre una progressi\xf3 C-G-F.",tips:["Usa alternate picking estricte per a la velocitat.","Comen\xe7a lent i augmenta el tempo gradualment."]},{title:"Cromatisme cap a la t\xf2nica",description:"Practica el pas crom\xe0tic cap a la t\xf2nica (B-Bb o Bb-B) com a final de frase.",tips:["El cromatisme final crea una resoluci\xf3 expressiva.","Acaba amb un vibrato sobre la t\xf2nica."]}]}]}}]);